INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(43411, 'Psalms 77:8', 'Psalms', 77, 8, 'ایا زمونږ سره یې تل بس کړه تلپاتې مینه؟ خپله وعده باندې به نور هغه تل نه دریږي؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms77_verse_8.mp3', '', 1761754199, 1761754199),
(43412, 'Psalms 77:9', 'Psalms', 77, 9, 'ایا خدای هېر کړل چې رحیم به اوسي؟ د خواخوږۍ ځای یې نیولی قهر؟»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms77_verse_9.mp3', '', 1761754199, 1761754199),
(43413, 'Psalms 77:10', 'Psalms', 77, 10, 'نو بیا مې وویل خپل ځان سره چې «څومره دردمند یمه زه چې خدای تعالی نور نه ښایي خپل قدرت زمونږ دپاره»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms77_verse_10.mp3', '', 1761754199, 1761754199),
(43414, 'Psalms 77:11', 'Psalms', 77, 11, 'زه یادوم به د ستا لوی کارونه ای څښتنه رایادوم به معجزې چې دې ښودلې پخوا', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms77_verse_11.mp3', '', 1761754199, 1761754199),
(43415, 'Psalms 77:12', 'Psalms', 77, 12, 'فکر به کړم ټولو کارونو باندې تا چې کړي زه به د ستا په زورورو عملونو باندې فکر کوم', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms77_verse_12.mp3', '', 1761754199, 1761754199),
(43416, 'Psalms 77:13', 'Psalms', 77, 13, 'ستا ټولې لارې سپېڅلې دي ای خدایه داسې لوی خدای بل ستا په شان نشته دی', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms77_verse_13.mp3', '', 1761754199, 1761754199),
(43417, 'Psalms 77:14', 'Psalms', 77, 14, 'ته هغه خدای یې چې کوې معجزې منځ د قومونو کې ښودلی خپل قدرت دی تا', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms77_verse_14.mp3', '', 1761754199, 1761754199),
(43418, 'Psalms 77:15', 'Psalms', 77, 15, 'په خپلو مټو دې خپل قوم خلاص کړی تا د یعقوب او د یوسف اولاده', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms77_verse_15.mp3', '', 1761754199, 1761754199),
(43419, 'Psalms 77:16', 'Psalms', 77, 16, 'کله چې سرې بحیرې ولیدلې ای خدایه چې اوبو ولیدې نو ووېرېدې تل د دریاب په لړزېدلو شولو', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms77_verse_16.mp3', '', 1761754199, 1761754199),
(43420, 'Psalms 77:17', 'Psalms', 77, 17, 'له ورېځو ډېر په شړق باران راغی تندر راپرېوت له اسمانه څخه ستا د برېښنا غشي هر خواته په ویشتلو شول', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms77_verse_17.mp3', '', 1761754199, 1761754199),
(43421, 'Psalms 77:18', 'Psalms', 77, 18, 'په توفان کې ستا د تندر اواز واورېدل شو ستا د برېښنا په رڼا ټوله دنیاګۍ رڼا شوه په لړزېدو او رپېدو شوه ځمکه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms77_verse_18.mp3', '', 1761754199, 1761754199),
(43422, 'Psalms 77:19', 'Psalms', 77, 19, 'تا د دریاب منځ کې قدم وواهه پورې وتلې له ژور دریابه خو ستا د پښو پلونه نه ښکارېدل', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms77_verse_19.mp3', '', 1761754199, 1761754199),
(43423, 'Psalms 77:20', 'Psalms', 77, 20, 'لکه د شپون په شان دې بوتلو خپل قوم په وسیله تا د موسی او هارون', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms77_verse_20.mp3', '', 1761754199, 1761754199),
(43424, 'Joshua 14:1', 'Joshua', 14, 1, 'هغه ځمکې چې بني اسراییلو د کنعان په خاوره کې تر لاسه کړې، العازار کاهن، د نون زوی یوشع او د قوم مشرانو د هغوی ترمنځ ووېشلې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua14_verse_1.mp3', '', 1761754199, 1761754199),
(43425, 'Joshua 14:2', 'Joshua', 14, 2, 'لکه څنګه چې څښتن د موسی په وسیله حکم کړی ؤ، د اردن د سیند په لوېدیځ کې د نهو قبیلو او نیمې قبیلې سیمې د پچې اچولو په وسیله وټاکل شوې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua14_verse_2.mp3', '', 1761754199, 1761754199),
(43426, 'Joshua 14:5', 'Joshua', 14, 5, 'نو اسراییلیانو د څښتن د امر له مخې چې موسی ته یې کړی ؤ، ځمکه ووېشله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua14_verse_5.mp3', '', 1761754199, 1761754199),
(43427, 'Joshua 14:6', 'Joshua', 14, 6, 'یوه ورځ د یهودا د قبیلې یو څو کسان په جلجال کې یوشع ته راغلل. د هغوی څخه یو کس کالیب د قنزي یفنه زوی هغه ته وویل: «ایا ستا په یاد دي چې څښتن خپل نبي موسی ته په قادش برنیع کې زما او ستا په هکله څه وویل؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua14_verse_6.mp3', '', 1761754199, 1761754199),
(43428, 'Joshua 14:7', 'Joshua', 14, 7, 'زه څلوېښت کلن وم کله چې د څښتن خدمتګار موسی زه د جاسوسۍ دپاره د قادش برنیع څخه د کنعان هېواد ته ولېږلم. نو څه چې ما لیدلي وو د هغو په اړه مې هغه ته حقیقت ووایه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua14_verse_7.mp3', '', 1761754199, 1761754199),
(43429, 'Joshua 14:8', 'Joshua', 14, 8, 'خو زما سره چې کوم کسان تللي وو، هغوی زمونږ خلک دې خاورې ته د تللو څخه ووېرول. خو ما په وفادارۍ سره د خپل څښتن خدای مقصد سرته ورساوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua14_verse_8.mp3', '', 1761754199, 1761754199),
(43430, 'Joshua 14:9', 'Joshua', 14, 9, 'په هماغه ورځ زه بېرته راغلم او موسی راته وویل: ‹څرنګه چې ته څښتن خدای ته وفادار وې، نو زه وعده کوم چې په کومه خاوره کې چې ته ګرځېدلی یې، هغه به د تل دپاره ستا او ستا د اولادې شي.›', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua14_verse_9.mp3', '', 1761754199, 1761754199),
(43431, 'Joshua 14:10', 'Joshua', 14, 10, 'خو اوس ګوره، زه لا تر اوسه ژوندی یم او پنځه څلوېښت کاله مخکې څښتن موسی ته دا خبره کړې وه او په هغه وخت کې د اسراییلو خلک په دښته کې سرګردانه ګرځېدل. ګورئ، زه اوس پنځه اتیا کلن یم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua14_verse_10.mp3', '', 1761754199, 1761754199),
(43432, 'Joshua 14:11', 'Joshua', 14, 11, 'زه نن هم د هماغه وخت په شان چې موسی ولېږلم قوي یم. کوم قوت چې ما په هغه وخت کې درلود، اوس یې هم لرم او د جګړې او نورو کارونو دپاره تیار یم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua14_verse_11.mp3', '', 1761754199, 1761754199),
(43433, 'Joshua 14:12', 'Joshua', 14, 12, 'اوس دغه غرنۍ سیمه چې په هغه ورځ څښتن زما سره د هغې وعده کړې وه ماته راکړه. تا په خپله په هغه ورځ واورېدل چې لوړ قدي عناقیان هلته اوسیږي او د هغوی ښارونه لوی دي او دېوالونه لري، خو لکه څنګه چې څښتن ویلي دي هغه به زما سره مرسته وکړي چې هغوی وشړم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua14_verse_12.mp3', '', 1761754199, 1761754199),
(43434, 'Joshua 14:13', 'Joshua', 14, 13, 'بیا یوشع کالیب ته برکت ورکړ او هغه ته یې د حبرون ښار د هغه د ملکیت په توګه ورکړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua14_verse_13.mp3', '', 1761754199, 1761754199),
(43435, 'Joshua 14:14', 'Joshua', 14, 14, 'نو حبرون تر اوسه پورې د کالیب د اولادې ملکیت دی، ځکه چې هغه په وفادارۍ سره د اسراییلو د څښتن خدای اطاعت کړی ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua14_verse_14.mp3', '', 1761754199, 1761754199),
(43436, 'Joshua 14:15', 'Joshua', 14, 15, 'له دې څخه مخکې حبرون د قریت اربع په نوم یادېده. اربع د عناقیانو په منځ کې یو لوی اتل ؤ. نو بیا په هېواد کې ارامي شوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua14_verse_15.mp3', '', 1761754199, 1761754199),
(43437, 'Jeremiah 22:1', 'Jeremiah', 22, 1, 'مالِک خُدائ ما ته وفرمائيل چې، ”تۀ د يهوداه د بادشاه محل ته ښکته لاړ شه او هلته دا پېغام بيان کړه،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah22_verse_1.mp3', '', 1761754199, 1761754199),
(43438, 'Jeremiah 22:2', 'Jeremiah', 22, 2, 'اے د يهوداه بادشاه، د مالِک خُدائ پېغام واوره، تاسو څوک چې د داؤد په تخت ناست يئ، تۀ، او ستا آفسران او ستا قوم څوک چې په دې دروازه تګ راتګ کوئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah22_verse_2.mp3', '', 1761754199, 1761754199),
(43439, 'Jeremiah 22:3', 'Jeremiah', 22, 3, 'مالِک خُدائ داسې فرمائى چې، اِنصاف او صداقت قائم کړئ. څوک چې لوټ شوے وى هغه د ظالم د لاس نه آزاد کړئ. په مسافرو، يتيمانو او کونډو ظلم او زياتے مۀ کوئ او بې‌ګناه وينه په دې ځائ کښې مۀ توئيوئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah22_verse_3.mp3', '', 1761754199, 1761754199),
(43440, 'Jeremiah 22:4', 'Jeremiah', 22, 4, 'کۀ چرې تاسو په احتياط سره زما په حکمونو عمل وکړئ، نو بيا هغه بادشاه څوک چې په يروشلم کښې د داؤد د اولاد نه د داؤد په تخت ناست دے د هغۀ بادشاهى او د هغۀ اولاد به قائم وى او هغه به د خپلو آفسرانو او د هغه خلقو سره چې په ګاډو او آسونو باندې سوارۀ دى د دې محل په دروازو راداخل شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah22_verse_4.mp3', '', 1761754199, 1761754199),
(43441, 'Jeremiah 22:5', 'Jeremiah', 22, 5, 'مالِک خُدائ فرمائى چې، کۀ چرې تاسو په دې حکمونو عمل ونۀ کړئ، قسم دې زما په خپل ذات وى چې دا محل به د خاورو ډېرے کړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah22_verse_5.mp3', '', 1761754199, 1761754199),
(43442, 'Jeremiah 22:6', 'Jeremiah', 22, 6, 'نو بيا مالِک خُدائ د يهوداه د بادشاه د محل په حقله داسې فرمائى، کۀ څۀ هم چې د يهوداه محل زما دپاره د جِلعاد په شان مېوه لرونکے او د لبنان د غرونو په شان شين او ښکلے دے، خو زۀ به په يقين سره دا په دشته بدل کړم لکه د هغه ښارونو په شان چې څوک په کښې نۀ اوسيږى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah22_verse_6.mp3', '', 1761754199, 1761754199),
(43443, 'Jeremiah 22:7', 'Jeremiah', 22, 7, 'زۀ به ستا د بربادۍ دپاره وسله بند جنګى لښکر درولېږم او هغوئ به ستا ستنې چې د دِيار د ښائسته ونو نه تيارې شوې دى راوباسى او په اور کښې به يې وغورزوى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah22_verse_7.mp3', '', 1761754199, 1761754199),
(43444, 'Jeremiah 22:8', 'Jeremiah', 22, 8, 'نو کله چې د ډېرو قومونو خلق په دې ښار باندې تېريږى نو بيا به د يو بل نه دا تپوس کوى چې، مالِک خُدائ ولې د دې لوئ ښار سره داسې سلوک وکړو؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah22_verse_8.mp3', '', 1761754199, 1761754199),
(43445, 'Jeremiah 22:9', 'Jeremiah', 22, 9, 'نو هغوئ ته به جواب ورکړے شى چې، د دې ښار سره داسې سلوک ځکه وشو چې هغوئ د خپل خُدائ پاک سره لوظ مات کړو او د نورو معبودانو عبادت او خِدمت يې وکړو.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah22_verse_9.mp3', '', 1761754199, 1761754199),
(43446, 'Jeremiah 22:10', 'Jeremiah', 22, 10, 'اے د يهوداه خلقو، د مړ شوى بادشاه يوسياه په حقله ژړا مۀ کوئ، او د هغۀ په مرګ ماتم مۀ کوئ. خو د دې په ځائ ډېره سخته ژړا د هغۀ د زوئ سلوم بادشاه په حقله وکړئ، څوک چې د مُلک نه شړلے شوے دے ځکه چې هغه به بيا کله هم واپس رانۀ شى، او نۀ به خپل ذاتى مُلک دوباره وګورى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah22_verse_10.mp3', '', 1761754199, 1761754199),
(43447, 'Jeremiah 22:11', 'Jeremiah', 22, 11, 'نو بيا مالِک خُدائ د يوسياه د زوئ سلوم په حقله فرمائى، څوک چې د پلار نه پس د يهوداه بادشاه جوړ شوے وو، ”هغه د دې ځائ نه لاړو او هغه به هيڅکله نۀ راواپس کيږى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah22_verse_11.mp3', '', 1761754199, 1761754199),
(43448, 'Jeremiah 22:12', 'Jeremiah', 22, 12, 'هغه به په هغه ځائ کښې مړ شى چرته چې هغوئ قېدى بوتلے دے او هغه به دا مُلک بيا دوباره هيڅکله ونۀ ګورى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah22_verse_12.mp3', '', 1761754199, 1761754199),
(43449, 'Jeremiah 22:13', 'Jeremiah', 22, 13, '”افسوس دے په يهويقيم څوک چې په ناجائزه او په زور سره په مزدورانو باندې خپل محل جوړوى، څوک چې په بې‌اِنصافۍ سره د هغې دېوالونه خېژوى، ځکه چې هغه په خپلو خلقو بغېر پېسو کار کوى. هغه هغوئ ته مزدورى هم نۀ ورکوى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah22_verse_13.mp3', '', 1761754199, 1761754199),
(43450, 'Jeremiah 22:14', 'Jeremiah', 22, 14, 'هغه وائى چې، زۀ به د خپل ځان دپاره يو لوئ محل جوړ کړم چې په کښې بره لوئې کوټې او ډيرې اوچتې کړکۍ وى او د لرګى کار به يې په خوشبودار دِيار سره وکړم او تک سور رنګ به ورکړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah22_verse_14.mp3', '', 1761754199, 1761754199),
(43451, 'Jeremiah 22:15', 'Jeremiah', 22, 15, 'خو د دِيار نه د ښائسته محلونو جوړول څوک لوئ بادشاه نۀ جوړوى. بې‌شکه ستا پلار، يوسياه، سره خو د خوړلو او څښلو دپاره هر څۀ ډېر تېر وُو، خو سره د دې هغه په خپله هره معامله کښې صادق او اِنصاف کوونکے وو، نو ځکه مالِک خُدائ ورله برکت ورکړو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah22_verse_15.mp3', '', 1761754199, 1761754199),
(43452, 'Jeremiah 22:16', 'Jeremiah', 22, 16, 'هغۀ به غريبانانو او محتاجو له امداد او اِنصاف ورکولو، د دې په بدل کښې ورته برکت مِلاو شو. نو د دې ښکاره مطلب دا دے، څوک چې داسې کوى نو هغه ما پېژنى، مالِک خُدائ داسې فرمائى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah22_verse_16.mp3', '', 1761754199, 1761754199),
(43453, 'Jeremiah 22:17', 'Jeremiah', 22, 17, 'خو ستاسو سترګې او زړۀ صرف د ناروا پېسو ګټلو طرف ته متوجه شوى دى، د بې‌ګناه خلقو وينه توئيوئ او دلته په هغوئ باندې ظلم او زياتے کوئ.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah22_verse_17.mp3', '', 1761754199, 1761754199),
(43454, 'Jeremiah 22:18', 'Jeremiah', 22, 18, 'نو مالِک خُدائ د يهوداه بادشاه، د يوسياه د زوئ يهويقيم په حقله فرمائى، ”خلق به ستا په مرګ ماتم نۀ کوى تر دې چې ستا په کور کښې به هيڅ څوک هم د غم او افسوس اظهار نۀ کوى او نۀ به څوک ووائى چې افسوس دے، اے مالِکه. افسوس ستا شان شوکت لاړو ختم شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah22_verse_18.mp3', '', 1761754199, 1761754199),
(43455, 'Jeremiah 22:19', 'Jeremiah', 22, 19, 'هغه به داسې ښخ کړے شى لکه څنګه چې يو خر ښخولے شى، هغه به راښکلے شى او د يروشلم د دروازو نه به بهر وغورزولے شى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah22_verse_19.mp3', '', 1761754199, 1761754199),
(43456, 'Jeremiah 22:20', 'Jeremiah', 22, 20, '”اے د يروشلم خلقو، بره لبنان ته لاړ شئ او چغې ووهئ، ستاسو د ژړا آواز دې په بسن کښې واورېدے شى، او د عباريم نه ژړا وکړئ، ځکه چې ستاسو ټول ملګرى تباه شوى دى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah22_verse_20.mp3', '', 1761754199, 1761754199),
(43457, 'Jeremiah 22:21', 'Jeremiah', 22, 21, 'ما په هغه وخت کښې تاسو ته خبردارے درکړو کله چې تاسو ښۀ په آرام وئ، خو تاسو ووئيل، مونږ مۀ تنګوه. د ځوانۍ نه ستاسو هم دا عادت وو، تاسو زما تابعدارى نۀ ده کړې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah22_verse_21.mp3', '', 1761754199, 1761754199),
(43458, 'Jeremiah 22:22', 'Jeremiah', 22, 22, 'زما د غضب طوفان به ستاسو ټول شپونکى جارُو کړى، او ستاسو ټول دوستان به جلاوطن کړى او هلته به غلامان شى او تاسو به د خپلو بدو عملونو په وجه سپک او شرمنده شئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah22_verse_22.mp3', '', 1761754199, 1761754199),
(43459, 'Jeremiah 22:23', 'Jeremiah', 22, 23, 'تاسو څوک چې په لبنان کښې اوسېږئ، او ځان ته مو د دِيار نه جاله جوړه کړې ده، تاسو به د دردونو په وجه داسې زبيرګى کوئ لکه چې يوه ښځه يې د ماشوم د پېدا کېدو په وخت کښې کوى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah22_verse_23.mp3', '', 1761754199, 1761754199),
(43460, 'Jeremiah 22:24', 'Jeremiah', 22, 24, 'مالِک خُدائ يهوياکين ته چې، د يهويقيم زوئ او د يهوداه بادشاه دے وفرمائيل، ”زما دې په خپل ذات قسم وى، کۀ چرې تۀ زما د ښى لاس ګوتمه هم ولې نۀ وے نو تۀ به بيا هم ما ايستلې او اخوا غورزولې وے.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah22_verse_24.mp3', '', 1761754199, 1761754199),
(43461, 'Jeremiah 22:25', 'Jeremiah', 22, 25, 'زۀ به تاسو هغه چا ته حواله کړم څوک چې ستا ژوند ختمول غواړى او د چا نه چې تۀ يرېږې. زۀ به تا د بابل بادشاه نبوکدنضر او د هغۀ خلقو ته حواله کړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah22_verse_25.mp3', '', 1761754199, 1761754199),
(43462, 'Jeremiah 22:26', 'Jeremiah', 22, 26, 'زۀ به تا او ستا مور د دې مُلک نه جلاوطن کړم، او تاسو به په پردى مُلک کښې مړۀ شئ، په هغه مُلک کښې چرته چې تاسو پېدا شوى نۀ يئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah22_verse_26.mp3', '', 1761754199, 1761754199),
(43463, 'Jeremiah 22:27', 'Jeremiah', 22, 27, 'تاسو به دې مُلک ته بيا هيڅکله هم واپس رانۀ شئ کوم چې تاسو غوښتل چې هغه بيا ووينئ.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah22_verse_27.mp3', '', 1761754199, 1761754199),
(43464, 'Jeremiah 22:28', 'Jeremiah', 22, 28, 'خلقو ووئيل چې، ”ولې دا سړے يهوياکين بادشاه د هغه مات منګى په شان دے څۀ، کوم چې غورزولے شوے وى او د هيچا په کار نۀ وى؟ هغه او د هغۀ بچى ولې په يو داسې مُلک کښې جلاوطن کړے شوى دى چې هغوئ ته هيڅ پته هم نۀ وى؟“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah22_verse_28.mp3', '', 1761754199, 1761754199),
(43465, 'Jeremiah 22:29', 'Jeremiah', 22, 29, 'اے زما وطنه، زما وطنه، زما وطنه. د مالِک خُدائ دې پېغام ته غوږ ونيسه،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah22_verse_29.mp3', '', 1761754199, 1761754199),
(43466, 'Jeremiah 22:30', 'Jeremiah', 22, 30, 'مالِک خُدائ دا فرمائى چې، ”دا کس په بې‌اولادو کښې حساب کړه، دا کس به په خپل ټول ژوند کښې نۀ خوشحاله او نۀ آباد شى. د هغۀ د اولاد نه به څوک هم آباد نۀ شى، او يو به هم نۀ د داؤد په تخت کښېنى، او نۀ به په يهوداه کښې حکومت وکړى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah22_verse_30.mp3', '', 1761754199, 1761754199),
(43467, 'Psalms 108:1', 'Psalms', 108, 1, 'زه په تا باندې ډاډه یمه ای خدایه زه به وایمه سندرې او د زړه له کومي ستا صفت کومه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms108_verse_1.mp3', '', 1761754199, 1761754199),
(43468, 'Psalms 108:2', 'Psalms', 108, 2, 'ای زما چنګه او ربابه رابېدار شئ! زه راویښ به سباوون کړم', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms108_verse_2.mp3', '', 1761754199, 1761754199),
(43469, 'Psalms 108:3', 'Psalms', 108, 3, 'ستا نه به وکړمه مننه ای څښتنه د قومونو منځ کې هم به ووایم ستا د ستاینې سندرې د ولسونو منځ کې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms108_verse_3.mp3', '', 1761754199, 1761754199),
(43470, 'Psalms 108:4', 'Psalms', 108, 4, 'له اسمانونو نه ده لوړه ستا تلپاتې مینه وفاداري دې تر فلکه رسي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms108_verse_4.mp3', '', 1761754199, 1761754199),
(43471, 'Psalms 108:5', 'Psalms', 108, 5, 'خدایه لویي دې کړه ظاهره اسمانونو باندې په ټوله ځمکه خپل جلال ښکاره کړه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms108_verse_5.mp3', '', 1761754199, 1761754199),
(43472, 'Psalms 108:6', 'Psalms', 108, 6, 'په خپل طاقت دې مونږه وژغوره او قبوله زما دعا کړه ترڅو نجات ومومي هغه خلک د هغه چا سره چې مینه کوې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms108_verse_6.mp3', '', 1761754199, 1761754199),
(43473, 'Psalms 108:7', 'Psalms', 108, 7, 'د خپل سپېڅلي ځای نه خدای خبرې وکړې «په خوشحالۍ به زه شکیم تقسیم کړم او د سکوت دره به ووېشم خپل قوم باندې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms108_verse_7.mp3', '', 1761754199, 1761754199),
(43474, 'Psalms 108:8', 'Psalms', 108, 8, 'جلعاد زما دی او منسي مې هم دی دی افرایم مې د زغرو خولۍ او یهودا مې شاهانه امسا ده', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms108_verse_8.mp3', '', 1761754199, 1761754199),
(43475, 'Psalms 108:9', 'Psalms', 108, 9, 'خو د موآب نه به کار واخلم د لګن په شان خپلې څپلۍ به د ادوم په لور ګوزارې کړمه په فلسطین باندې به چیغه د بریا وکړمه»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms108_verse_9.mp3', '', 1761754199, 1761754199),
(43476, 'Psalms 108:10', 'Psalms', 108, 10, 'څوک به مې بوځي د برجونو ښار ته؟ څوک به مې بوځي د ادوم ښار ته؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms108_verse_10.mp3', '', 1761754199, 1761754199),
(43477, 'Psalms 108:11', 'Psalms', 108, 11, 'تا په رښتیا سره پرې ایښي یو مونږ؟ زمونږ د لښکرو سره نور نه ځې ته؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms108_verse_11.mp3', '', 1761754199, 1761754199),
(43478, 'Psalms 108:12', 'Psalms', 108, 12, 'مرسته مو وکړه د دښمن په خلاف نه لري ګټه د انسان مرسته', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms108_verse_12.mp3', '', 1761754199, 1761754199),
(43479, 'Psalms 108:13', 'Psalms', 108, 13, 'مونږ به کامیاب شو چې خدای مل وي زمونږ هغه سرکوب به کړي زمونږ دښمنان', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms108_verse_13.mp3', '', 1761754199, 1761754199),
(43480, 'Jeremiah 15:1', 'Jeremiah', 15, 1, 'بيا مالِک خُدائ ما ته وفرمائيل، ”کۀ چرې موسىٰ او سموئيل هم دلته ودرېدلى وے او ما ته يې د دې خلقو په حقله مِنت زارى کړے وے، نو زما زړۀ به دوئ ته مائل شوے نۀ وو. هغوئ زما د حضور نه وشړه، او پرېږده چې ځى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah15_verse_1.mp3', '', 1761754199, 1761754199),
(43481, 'Jeremiah 15:2', 'Jeremiah', 15, 2, 'او کۀ چرې هغوئ ستا نه تپوس وکړى چې مونږ چرته لاړ شُو؟ هغوئ ته ووايه، چې مالِک خُدائ داسې فرمائى، د کومو خلقو په نصيب کښې چې په وبا مړۀ کېدل دى هغوئ دې په وبا مړۀ شى، د چا په نصيب کښې چې په جنګ کښې مړۀ کېدل دى هغوئ دې په جنګ مړۀ شى، د چا په نصيب کښې چې په لوږه مړۀ کېدل دى هغوئ دې په لوږه مړۀ شى، او د چا په نصيب کښې چې جلاوطنى ده هغه دې جلاوطن کړے شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah15_verse_2.mp3', '', 1761754199, 1761754199),
(43482, 'Jeremiah 15:3', 'Jeremiah', 15, 3, 'مالِک خُدائ فرمائى چې، زۀ به څلور قسمه تباه کوونکى ورولېږم. تُوره د هغوئ د وژلو دپاره، سپى چې د هغوئ لاشونه راکاږى، ټپوسان چې هغوئ تېر کړى او ځنګلى ځناور چې هغوئ ختم کړى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah15_verse_3.mp3', '', 1761754199, 1761754199),
(43483, 'Jeremiah 15:4', 'Jeremiah', 15, 4, 'د يهوداه بادشاه منسى د حزقياه د زوئ په وجه چا چې بد کارونه په يروشلم کښې کړى وُو، زۀ به خپل خلق د دُنيا بادشاهانو دپاره د يرې يو مثال جوړ کړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah15_verse_4.mp3', '', 1761754199, 1761754199),
(43484, 'Jeremiah 15:5', 'Jeremiah', 15, 5, 'اے يروشلمه څوک به په تاسو رحم وکړى؟ او څوک به په تاسو وير وکړى؟ ستاسو داسې همدرد نشته چې ستاسو تپوس له راشى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah15_verse_5.mp3', '', 1761754199, 1761754199),
(43485, 'Jeremiah 15:6', 'Jeremiah', 15, 6, 'مالِک خُدائ فرمائى چې، تاسو زۀ رد کړے يم، او بار بار مو ما ته شا کړې ده. نو اوس به زۀ خپل لاس ستاسو د بربادۍ دپاره دراوږد کړم، نو په تاسو زۀ نور رحم نۀ شم کولے.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah15_verse_6.mp3', '', 1761754199, 1761754199),
(43486, 'Jeremiah 15:7', 'Jeremiah', 15, 7, 'زۀ به تاسو، ستاسو د ښارونو په دروازو کښې داسې د يو بل نه جدا کړم لکه څنګه چې غنم او بوس جدا کولے شى. او تاسو نه به ستاسو بچى واخلم کوم چې په تاسو ډېر ګران دى. زۀ به خپل قوم تباه کړم، ځکه چې هغوئ د خپلو خرابو طريقو پرېښودو نه اِنکار کړے دے.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah15_verse_7.mp3', '', 1761754199, 1761754199),
(43487, 'Jeremiah 15:8', 'Jeremiah', 15, 8, 'ستاسو په مُلک کښې به کونډې د سمندر په غاړه د شګو نه هم ډيرې وى. په نيمه ورځ به زۀ د ځوانانو په ميندو باندې تباهى راولم. او ناګهانه به په دوئ پرېشانى او دهشت راولم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah15_verse_8.mp3', '', 1761754199, 1761754199),
(43488, 'Jeremiah 15:9', 'Jeremiah', 15, 9, 'د اوو بچو مور د غم نه بې‌هوشه پرته ده او ساه نۀ شى اخستلے، د هغې د بچو د ژوند رڼا ختمه شوه. هغه رسوا او شرمنده شوې ده. په هغوئ کښې چې څوک پاتې دى هغه به زۀ د دشمنانو په تُوره مړۀ کړم. دا د مالِک خُدائ وينا ده.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah15_verse_9.mp3', '', 1761754199, 1761754199),
(43489, 'Jeremiah 15:10', 'Jeremiah', 15, 10, 'نو ما بيا ووئيل چې، کاش چې زۀ د مور نه پېدا شوے هم نۀ وے. زۀ چې چرته هم ځم نو هلته خلق زما مخالف دى او جنګ راسره کوى. نۀ مې چا ته قرض ورکړے دے او نۀ مې د چا نه قرض اخستے دے، خو بيا هم دوئ ټول په ما لعنت وائى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah15_verse_10.mp3', '', 1761754199, 1761754199),
(43490, 'Jeremiah 15:11', 'Jeremiah', 15, 11, 'مالِک خُدائ فرمائى چې، ”په يقين سره به زۀ ستا ښۀ مقصد دپاره خيال وساتم، يرمياه. او په يقين سره ستا دشمنان به ستا نه دا وغواړى چې تۀ د تکليف او مصيبت په وخت کښې د هغوئ دپاره ما ته سوال زارى وکړې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah15_verse_11.mp3', '', 1761754199, 1761754199),
(43491, 'Jeremiah 15:12', 'Jeremiah', 15, 12, 'آيا څوک هغه د اوسپنې او د پيتلو نه جوړ شوے سيخ ماتولے شى کوم چې د شمال د خوا نه راځى؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah15_verse_12.mp3', '', 1761754199, 1761754199),
(43492, 'Jeremiah 15:13', 'Jeremiah', 15, 13, 'زۀ به ستاسو مال دولت او خزانې مفتې دشمنانو ته د لوټ کولو دپاره حواله کړم، ځکه دا ستاسو د هغه ګناهونو په وجه چې تاسو په ټول مُلک کښې کړې دى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah15_verse_13.mp3', '', 1761754199, 1761754199),
(43493, 'Jeremiah 15:14', 'Jeremiah', 15, 14, 'زۀ به تاسو د دشمنانو په لاس يو داسې مُلک ته په غلامۍ ولېږم چې تاسو ته د هغې هيڅ پته نۀ وى. ځکه چې زما غصه د اور په شان رابله شوې ده او دا به د تل دپاره بليږى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah15_verse_14.mp3', '', 1761754199, 1761754199),
(43494, 'Jeremiah 15:15', 'Jeremiah', 15, 15, 'بيا ما ووئيل چې، ”اے مالِکه خُدايه، تا ته د هر څۀ پته ده، څۀ چې ما سره کيږى. نو راشه او زما مدد وکړه. زما د دشمنانو نه بدل واخله او هغوئ ته دومره صبر مۀ کوه چې زما د وژلو موقع ورته مِلاو شى. ګوره خو ما په خپل ځان دا ټوله بې‌عزتى ستا د خاطره تېره کړې ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah15_verse_15.mp3', '', 1761754199, 1761754199),
(43495, 'Jeremiah 15:16', 'Jeremiah', 15, 16, 'اے مالِکه، ربُ الافواجه خُدايه، هرکله به چې ستا کلام په ما نازل شو، نو هغه ما وخوړلو، هغۀ ما ته او زما زړۀ ته خوشحالى راکړه، ځکه چې ما پورې ستا نوم تړلے شوے دے.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah15_verse_16.mp3', '', 1761754199, 1761754199),
(43496, 'Jeremiah 15:17', 'Jeremiah', 15, 17, 'زۀ د هغه خلقو سره شامل نۀ شوم چې خندا او خوشحالى به يې کوله. زۀ ځان ته کښېناستم ځکه چې ستا لاس په ما وو. او د هغوئ د ګناهونو په وجه زما قهر راوچت شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah15_verse_17.mp3', '', 1761754199, 1761754199),
(43497, 'Jeremiah 15:18', 'Jeremiah', 15, 18, 'زما درد ولې نۀ ختميږى؟ او زما زخمونه ولې لا علاجه دى او نۀ رغيږى؟ ستا مدد زما دپاره داسې نا باوره شو لکه موسمى لختى، لکه د هغه چينې په شان چې اوچه شوې وى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah15_verse_18.mp3', '', 1761754199, 1761754199),
(43498, 'Jeremiah 15:19', 'Jeremiah', 15, 19, 'نو مالِک خُدائ په جواب کښې ما ته وفرمائيل، ”کۀ تۀ واپس راشې، نو زۀ به تا له بيا خپل مقام درکړم چې تۀ زما خِدمت وکړې. کۀ تۀ د بې‌مطلبه خبرو په ځائ زما قيمتى کلام بيان کړې، نو تۀ به زما پېغمبر يې. دا خلق دې ضرور تا له راشى بلکې تۀ د هغوئ په شان مۀ جوړېږه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah15_verse_19.mp3', '', 1761754199, 1761754199),
(43499, 'Jeremiah 15:20', 'Jeremiah', 15, 20, 'مالِک خُدائ فرمائى چې، زۀ به تا د دې خلقو په وړاندې د پيتلو قوى دېوال جوړ کړم. هغوئ به ستا خِلاف جنګ کوى، خو هغوئ به تا له شکست نۀ شى درکولے، ځکه چې زۀ تا سره يم چې تا وساتم او خلاصون درکړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah15_verse_20.mp3', '', 1761754199, 1761754199),
(43500, 'Jeremiah 15:21', 'Jeremiah', 15, 21, 'زۀ به تا د شريرانو د لاسونو نه وساتم، او د ظالمانو د زور او لاسونو نه به درله خلاصون درکړم.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah15_verse_21.mp3', '', 1761754199, 1761754199),
(43501, 'Psalms 22:1', 'Psalms', 22, 1, 'زما خدایه، زما خدایه، تا زه ولې یم پرې ایښی؟ شولې دومره لېرې ته ولې له ما نه؟ نه مې اورې ته زګېروي، ولې نه راځې خلاصون له؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms22_verse_1.mp3', '', 1761754199, 1761754199),
(43502, 'Psalms 22:2', 'Psalms', 22, 2, 'هره ورځ درته فریاد کړم زما خدایه خو ځواب نه راکوې ته هره شپه درته فریاد کړم خو ما ونه موند ارام', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms22_verse_2.mp3', '', 1761754199, 1761754199),
(43503, 'Psalms 22:3', 'Psalms', 22, 3, 'خو ته سپېڅلی یې او ناست یې پاچاهي کړې قبلوې د اسراییلو ثناګانې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms22_verse_3.mp3', '', 1761754199, 1761754199),
(43504, 'Psalms 22:4', 'Psalms', 22, 4, 'په تا وکړلو توکل زمونږ نیکونو چې توکل یې په تا وکړ تا خلاصون هغوی ته ورکړ', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms22_verse_4.mp3', '', 1761754199, 1761754199),
(43505, 'Psalms 22:5', 'Psalms', 22, 5, 'هغوی تاته فریاد وکړ او تا خلاص کړل له خطره چې توکل یې په تا وکړ هغوی نه شولو مایوسه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms22_verse_5.mp3', '', 1761754199, 1761754199),
(43506, 'Psalms 22:6', 'Psalms', 22, 6, 'خو د خلکو په نظر کې زه چینجی یم انسان نه یم خلک خاندي په ما پورې او په سپکه راته ګوري', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms22_verse_6.mp3', '', 1761754199, 1761754199),
(43507, 'Psalms 22:7', 'Psalms', 22, 7, 'وهي ما باندې ملنډې چې هرڅوک وویني ما راوباسي راته ژبې خوځوي راته سرونه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms22_verse_7.mp3', '', 1761754199, 1761754199),
(43508, 'Psalms 22:8', 'Psalms', 22, 8, 'دوی وایي: «په څښتن دې تکیه وکړي چې خلاصون ورکړي ځکه څښتن ورسره مینه کوي نو هغه دې وژغوري»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms22_verse_8.mp3', '', 1761754199, 1761754199),
(43509, 'Psalms 22:9', 'Psalms', 22, 9, 'همدا ته وې چې دې راوویستم خوندي د مور د خېټې نه زه ماشوم ومه د غېږې تا ساتنه کړه زما', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms22_verse_9.mp3', '', 1761754199, 1761754199),
(43510, 'Psalms 22:10', 'Psalms', 22, 10, 'زه چې شومه راپیدا له هغې ورځې تا په ما کولو پام له کوم وخت نه چې پیدا شوم همدا ته وې زما خدای', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms22_verse_10.mp3', '', 1761754199, 1761754199);